<style>
.jf-admin{box-sizing:border-box;max-width:1120px;margin:0 auto;padding:28px 32px 48px;color:#202938;font:14px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}
.jf-admin *{box-sizing:border-box}.jf-admin h1,.jf-admin h2,.jf-admin p{margin-top:0}.jf-heading{display:flex;align-items:center;gap:14px;margin:0 0 24px}.jf-heading--spread{justify-content:space-between}.jf-heading h1{margin:0;color:#182230;font-size:24px;font-weight:650;line-height:1.25}.jf-heading p{margin:5px 0 0;color:#718096;font-size:13px}.jf-heading__icon,.jf-form-card__icon{display:grid;place-items:center;flex:none;color:#536dfe;background:#eef1ff;border-radius:12px}.jf-heading__icon{width:48px;height:48px}.jf-back{display:inline-flex;align-items:center;gap:7px;margin:0 0 20px;color:#536dfe;text-decoration:none;font-weight:550}.jf-back:hover,.jf-form-card:hover strong{color:#3446c5}.jf-grid{display:grid;gap:12px}.jf-form-card{display:flex;align-items:center;gap:16px;min-width:0;padding:18px 20px;color:inherit;text-decoration:none;background:#fff;border:1px solid #e7eaf0;border-radius:12px;box-shadow:0 2px 8px #18223008;transition:border-color .15s,box-shadow .15s}.jf-form-card:hover{border-color:#c7ceff;box-shadow:0 5px 16px #1822300d}.jf-form-card__icon{width:42px;height:42px}.jf-form-card__main{display:grid;gap:3px;min-width:0;flex:1}.jf-form-card__main strong{overflow:hidden;color:#202938;font-size:15px;text-overflow:ellipsis}.jf-form-card__main small,.jf-form-card__date small{color:#8792a2;font-size:12px}.jf-count{display:inline-flex;align-items:center;justify-content:center;padding:5px 10px;color:#4655c7;background:#eef1ff;border-radius:20px;font-size:12px;font-weight:650;white-space:nowrap}.jf-count--large{padding:8px 13px;font-size:13px}.jf-form-card__date{display:grid;gap:3px;color:#4b5563;font-size:12px}.jf-chevron{color:#9aa4b2}.jf-empty{display:grid;justify-items:center;gap:10px;padding:50px 20px;color:#9aa4b2;background:#fff;border:1px dashed #d9dee8;border-radius:12px}.jf-empty p{margin:0;color:#667085}.jf-notice{margin-bottom:18px;padding:12px 15px;color:#126b4c;background:#e8f7ef;border:1px solid #c7ead8;border-radius:9px}.jf-response-list{display:grid;gap:14px}.jf-response-card{padding:20px 22px;background:#fff;border:1px solid #e7eaf0;border-radius:12px;box-shadow:0 2px 8px #18223008}.jf-response-card__head{display:flex;align-items:center;justify-content:space-between;gap:14px;padding-bottom:15px;border-bottom:1px solid #edf0f4}.jf-response-id{color:#273449;font-size:14px}.jf-date{display:inline-flex;align-items:center;gap:6px;color:#7b8797;font-size:12px}.jf-data-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;padding:17px 0}.jf-data-item{display:grid;gap:4px;min-width:0;padding:11px 13px;background:#f7f8fb;border-radius:8px}.jf-data-item>span{color:#7a8493;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.04em}.jf-data-item strong{overflow-wrap:anywhere;color:#263244;font-size:14px;font-weight:550}.jf-response-card__actions{display:flex;align-items:center;gap:9px;padding-top:14px;border-top:1px solid #edf0f4}.jf-response-card__actions form,.jf-detail-card form{margin:0}.jf-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:34px;padding:7px 11px;border:1px solid transparent;border-radius:7px;font:600 12px/1.2 system-ui,-apple-system,"Segoe UI",sans-serif;text-decoration:none;cursor:pointer}.jf-button--primary{color:#fff;background:#536dfe}.jf-button--primary:hover{color:#fff;background:#4055dc}.jf-button--danger{color:#b42332;background:#fff;border-color:#f0c9ce}.jf-button--danger:hover{color:#fff;background:#c43d4b;border-color:#c43d4b}.jf-detail-card{max-width:820px}.jf-detail-card h2{margin:0;padding-bottom:15px;border-bottom:1px solid #edf0f4;font-size:16px}.jf-data-grid--detail{grid-template-columns:1fr;padding:17px 0}.jf-data-grid--detail .jf-data-item{grid-template-columns:minmax(130px,.35fr) 1fr;align-items:center}.jf-detail-card form{padding-top:15px;border-top:1px solid #edf0f4}
@media(max-width:650px){.jf-admin{padding:20px 14px 32px}.jf-heading h1{font-size:20px}.jf-form-card{flex-wrap:wrap;padding:14px}.jf-form-card__date{width:100%;padding-left:58px}.jf-response-card{padding:16px}.jf-response-card__head{align-items:flex-start;flex-direction:column}.jf-data-grid--detail .jf-data-item{grid-template-columns:1fr}}
</style>
